import re
import sqlite3


def get_book_details(book_id):
    if not isinstance(book_id, str):
        raise TypeError("Book ID must be a string")

    if not re.fullmatch(r"[A-Za-z0-9]+", book_id):
        raise ValueError("Book ID must contain only letters and digits")

    db_path = "./Test/CWE-89_03/books.db"

    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(
                "SELECT book_id, title, author, price FROM books WHERE book_id = ?",
                (book_id,)
            )
            row = cursor.fetchone()
            return row if row is not None else None
    except sqlite3.Error as exc:
        raise RuntimeError(f"Failed to retrieve book details for book_id={book_id}") from exc
